import{_ as r,a0 as l,w as p,s,ao as u,I as i,x as e,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux 有問必答：如何在 Linux 上自動設置 JAVA_HOME 環境變量 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在 Linux 上自動設置 JAVA_HOME 環境變量 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在 Linux 上自動設置 JAVA_HOME 環境變量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在 Linux 上自動設置 JAVA_HOME 環境變量 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151116 Linux FAQs with Answers--How to set JAVA_HOME environment variable automatically on Linux","title":"Linux 有問必答：如何在 Linux 上自動設置 JAVA_HOME 環境變量","tag":"201511","desc":""},"relativePath":"201511/20151116 Linux FAQs with Answers--How to set JAVA_HOME environment variable automatically on Linux.md","filePath":"[post].md"}'),m={name:"201511/20151116 Linux FAQs with Answers--How to set JAVA_HOME environment variable automatically on Linux.md"};function A(x,t,J,d,v,_){const n=l("Link");return p(),s("div",null,[t[16]||(t[16]=u(`<h1 id="linux-有問必答-如何在-linux-上自動設置-java-home-環境變量" tabindex="-1">Linux 有問必答：如何在 Linux 上自動設置 JAVA_HOME 環境變量 <a class="header-anchor" href="#linux-有問必答-如何在-linux-上自動設置-java-home-環境變量" aria-label="Permalink to “Linux 有問必答：如何在 Linux 上自動設置 JAVA_HOME 環境變量”">​</a></h1><blockquote><p><strong>問題</strong>：我需要在我的 Linux 機器上編譯 Java 程序。為此我已經安裝了 JDK (Java Development Kit)，而現在我正試圖設置 JAVA_HOME 環境變量使其指向安裝好的 JDK 。關於在 Linux 上設置 JAVA_HOME 環境變量，最受推崇的辦法是什麼？</p></blockquote><p>許多 Java 程序或基於 Java 的<em>集成開發環境</em> (IDE)都需要設置好 JAVA_HOME 環境變量。該變量應指向 <em>Java 開發工具包</em> (JDK)或 <em>Java 運行時環境</em> (JRE)的安裝目錄。JDK 不僅包含了 JRE 提供的一切，還帶有用於編譯 Java 程序的額外的二進制代碼和庫文件（例如編譯器，調試器及 JavaDoc 文檔生成器）。JDK 是用來構建 Java 程序的，如果只是運行已經構建好的 Java 程序，單獨一份 JRE 就足夠了。</p><p>當您正試圖設置 JAVA_HOME 環境變量時，麻煩的事情在於 JAVA_HOME 變量需要根據以下幾點而改變：(1) 您是否安裝了 JDK 或 JRE；(2) 您安裝了哪個版本；(3) 您安裝的是 Oracle JDK 還是 Open JDK。</p><p>因此每當您的開發環境或運行時環境發生改變（例如為 JDK 更新版本）時，您需要根據實際情況調整 JAVA_HOME 變量，而這種做法是繁重且缺乏效率的。</p><p>以下 export 命令能為您<strong>自動設置</strong> JAVA_HOME 環境變量，而無須顧及上述的因素。</p><p>若您安裝的是 JRE：</p><pre><code>export JAVA_HOME=$(dirname $(dirname $(readlink -f $(which java))))
</code></pre><p>若您安裝的是 JDK：</p><pre><code>export JAVA_HOME=$(dirname $(dirname $(readlink -f $(which javac))))
</code></pre><p>根據您的情況，將上述命令中的一條寫入 ~/.bashrc（或 /etc/profile）文件中，它就會永久地設置好 JAVA_HOME 變量。</p><p>注意，由於 java 或 javac 可以建立起多個層次的符號鏈接，為此&quot;readlink -f&quot;命令是用來獲取它們真正的執行路徑的。</p><p>舉個例子，假如您安裝的是 Oracle JRE 7，那麼上述的第一條 export 命令將自動設置 JAVA_HOME 為：</p><pre><code>/usr/lib/jvm/java-7-oracle/jre
</code></pre><p>若您安裝的是 Open JDK 第8版，那麼第二條 export 命令將設置 JAVA_HOME 為：</p><pre><code>/usr/lib/jvm/java-8-openjdk-amd64
</code></pre><p><img src="https://c1.staticflickr.com/1/700/22961948071_c73a3261dd_c.jpg" alt=""></p>`,17)),i("p",null,[t[1]||(t[1]=e("簡而言之，這些 export 命令會在您重裝/升級您的JDK/JRE，或",-1)),a(n,{href:"http://ask.xmodulo.com/change-default-java-version-linux.html"},{default:o(()=>[...t[0]||(t[0]=[e("更換默認 Java 版本",-1)])]),_:1}),t[2]||(t[2]=e("時自動更新 JAVA_HOME 變量。您不再需要手動調整它。",-1))]),t[17]||(t[17]=i("hr",null,null,-1)),i("p",null,[t[4]||(t[4]=e("via: ",-1)),a(n,{href:"http://ask.xmodulo.com/set-java_home-environment-variable-linux.html"},{default:o(()=>[...t[3]||(t[3]=[e("http://ask.xmodulo.com/set-java_home-environment-variable-linux.html",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=e("作者：",-1)),a(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...t[5]||(t[5]=[e("Dan Nanni",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),a(n,{href:"https://github.com/Ricky-Gong"},{default:o(()=>[...t[6]||(t[6]=[e("Ricky-Gong",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const V=r(m,[["render",A]]);export{f as __pageData,V as default};
